window.StrictDoc.search.nodesByMid = {"1":{"MID":"234ed10991be4784b614e3c0585eee44","TITLE":"Patient monitor interface","_LINK":"1-Patient-monitor-interface"},"2":{"MID":"f20012f5448d4aaca84cebe480d3a059","UID":"IRS001","TITLE":"attach","STATEMENT":"attach shall accept a Human and shall select the default limit profile for that patient's age.","_LINK":"IRS001"},"3":{"MID":"b32db725905a4dbc8cc4b711b62e29ea","UID":"IRS002","TITLE":"start and stop","STATEMENT":"start shall begin monitoring when a patient is attached and shall reject a start when no patient is attached. stop shall end monitoring.","_LINK":"IRS002"},"4":{"MID":"027d7e085b0e4f48aa6e7816e7e1668f","UID":"IRS003","TITLE":"set_limits","STATEMENT":"set_limits shall accept an in-range AlarmLimits and shall raise LimitRejected without changing the limits already in effect when the command is out of range.","_LINK":"IRS003"},"5":{"MID":"fb0beac390c44eda97268c7ed1dd4d24","UID":"IRS004","TITLE":"vitals and alarms","STATEMENT":"vitals shall return a reading whose valid flag is true only while monitoring is running with a valid sensor. alarms shall return the active alarm set and shall return an empty set when monitoring is not running.","_LINK":"IRS004"},"6":{"MID":"524ad00340d140a995a0394ea53c52e2","UID":"IRS005","TITLE":"SOAP GetPatient","STATEMENT":"GetPatient shall accept a patientId and shall return that patient's identity, age, vitals, and sensor validity, or a SOAP fault when the patient is unknown or the request is malformed.","_LINK":"IRS005"},"7":{"MID":"1243e7df0cf64c2abe81cd822d13dc2e","UID":"IRS006","TITLE":"ReadyAPI patient resource","STATEMENT":"GET /patients/{patient_id} shall return that patient's identity, age, vitals, and sensor validity as JSON, or status 404 when the patient is unknown.","_LINK":"IRS006"},"8":{"MID":"23b3e6abbdd04778ac23043af3a69a49","TITLE":"Software units","_LINK":"1-Software-units"},"9":{"MID":"ca4e83f94d1a4e478107c342ae102c50","UID":"SDD001","TITLE":"Human stimulus","STATEMENT":"Human and its patient subclasses shall hold the patient stimulus, including age and sensor validity, and shall not evaluate alarms.","_LINK":"SDD001"},"10":{"MID":"67b0f08443c34595ac765b1e252c0a59","UID":"SDD002","TITLE":"AlarmLimits unit","STATEMENT":"AlarmLimits shall hold one limit profile and accept_limits shall decide whether a set_limits command is inside the allowed range.","_LINK":"SDD002"},"11":{"MID":"07fc806f96484801844ca1072d1cdd12","UID":"SDD003","TITLE":"AlarmEvaluator unit","STATEMENT":"AlarmEvaluator shall be a pure function from a patient and a limit profile to a set of alarms, including the inclusive-limit and sensor-fault rules.","_LINK":"SDD003"},"12":{"MID":"a8be8d45a43d44a2a3768b909e14d439","UID":"SDD004","TITLE":"PatientMonitor unit","STATEMENT":"PatientMonitor shall own attach, start, stop, set_limits, vitals, and alarms, and shall keep the last accepted limits when a command is rejected.","_LINK":"SDD004"},"13":{"MID":"deb21d643d4a41e79990cb26fdd16a50","UID":"SDD005","TITLE":"No lower-class segregation","STATEMENT":"The pytest harness shall stay separate from the monitor package. No segregation is claimed for a lower software safety class, and every software item in this increment remains at Class C.","_LINK":"SDD005"},"14":{"MID":"3574c911cb0e43d5a55f15221f8b35fb","UID":"SDD006","TITLE":"SOAP patient units","STATEMENT":"SoapPatientService shall serve registered Human records over SOAP 1.1 GetPatient, and SoapPatientDevice shall be the client that turns a successful response into a Human.","_LINK":"SDD006"},"15":{"MID":"08e73e1acc2f41d490188ecd1c328494","UID":"SDD007","TITLE":"ReadyAPI patient units","STATEMENT":"ReadyApiPatientService shall serve GET /patients/{patient_id}, and ReadyApiPatientDevice shall be the client that turns a successful JSON document into a Human.","_LINK":"SDD007"},"16":{"MID":"9da370db73624411ba085ab6602d301c","TITLE":"Planning for this mock increment","_LINK":"1-Planning-for-this-mock-increment"},"17":{"MID":"15883e7cb06545cfb672933df5d05e68","UID":"SDP001","TITLE":"Confirmed software safety class","STATEMENT":"This mock shall be developed using the IEC 62304:2006+AMD1:2015 Class C activity set. The user confirmed Class C on 2026-10-20. These records do not constitute a claim of conformity.","_LINK":"SDP001"},"18":{"MID":"3ca986df0efc48f39faa522e103fbaee","UID":"SDP002","TITLE":"Coding standard","STATEMENT":"Python in this increment shall follow PEP 8 and shall pass Ruff using the configuration in pyproject.toml.","_LINK":"SDP002"},"19":{"MID":"0772fd40b737463b8393982022cfb96c","UID":"SDP003","TITLE":"Verification order and record","STATEMENT":"Verification shall run unit tests, then integration tests, then software system tests. make test shall record the result in docs/pytest-report.html.","_LINK":"SDP003"},"20":{"MID":"0fc1f0b4f26b4c49b79bb0c110b25d69","UID":"SDP004","TITLE":"SOUP identification","STATEMENT":"SOUP shall be identified as pytest 9.1.1 and pytest-html 4.2.0 from pytest-dev, Ruff 0.17.1 from Astral, StrictDoc 0.30.1, and readyapi 0.112.0 from KhulnaSoft, with those versions pinned in uv.lock. readyapi 0.112.0 is a runtime dependency of the ReadyAPI patient device. Published-anomaly review is not completed, and this mock is not released medical-device software.","_LINK":"SDP004"},"21":{"MID":"7b35393675744e97a84d38aa4993f84a","UID":"SDP005","TITLE":"Traceability","STATEMENT":"Traceability shall connect system requirements, software requirements, design, interfaces, test descriptions, and tests by UID relations and by Implements and Verifies comments.","_LINK":"SDP005"},"22":{"MID":"1c5508160a924db384ef2e9e3b8ce3df","UID":"SDP006","TITLE":"Resource acceptance not applicable","STATEMENT":"This design has no fixed-size buffers. Memory-overflow acceptance criteria do not apply to this increment.","_LINK":"SDP006"},"23":{"MID":"b6c7821477f84f55ac37647a0b2bdb30","TITLE":"Mock patient monitor system requirements","_LINK":"1-Mock-patient-monitor-system-requirements"},"24":{"MID":"520e9d8644be47bba59bc4d73cb908e9","UID":"SRS001","TITLE":"Present vital signs","STATEMENT":"When monitoring is running and the sensor is valid, the monitor shall present the attached patient's heart rate in beats per minute, oxygen saturation in percent, systolic and diastolic blood pressure in millimetres of mercury, and temperature in degrees Celsius.","_LINK":"SRS001"},"25":{"MID":"5a30d6596d104caf8726a8c259c169a3","UID":"SRS002","TITLE":"Alarm on out-of-limit vitals","STATEMENT":"The monitor shall raise an alarm when a valid vital sign is outside the limit profile for that patient's age.","_LINK":"SRS002"},"26":{"MID":"de63b8f0de0241d18e5390bb5d595ef0","UID":"SRS003","TITLE":"Sensor-fault alarm","STATEMENT":"The monitor shall raise a sensor-fault alarm when the measurement is invalid, and shall not raise a vital-sign alarm from an invalid measurement.","_LINK":"SRS003"},"27":{"MID":"238866a151f74d8bb3437b998cb9a171","UID":"SRS004","TITLE":"Reject an out-of-range limit command","STATEMENT":"The monitor shall reject an alarm-limit command outside the allowed range and shall leave the limits already in effect unchanged.","_LINK":"SRS004"},"28":{"MID":"15dc89d9a33a4d0e809b2c719d9322f8","UID":"SRS005","TITLE":"Publish an HTML test report","STATEMENT":"The test harness shall run the software system tests and publish an HTML results report.","_LINK":"SRS005"},"29":{"MID":"21ef4528310e446bb1658266f05af4ec","UID":"SRS006","TITLE":"Obtain a patient over SOAP","STATEMENT":"The SOAP patient device shall obtain identity, age, vitals, and sensor validity from a SOAP 1.1 GetPatient response.","_LINK":"SRS006"},"30":{"MID":"d61fb6a797ba4944a8ac690c22ed16eb","UID":"SRS007","TITLE":"Obtain a patient from ReadyAPI","STATEMENT":"The ReadyAPI patient device shall obtain identity, age, vitals, and sensor validity from the ReadyAPI patient resource.","_LINK":"SRS007"},"31":{"MID":"de95c43e1c3b4069b7377217a31d937e","TITLE":"Monitor behavior","_LINK":"1-Monitor-behavior"},"32":{"MID":"4f691b1749f1468cb022bf51c2fcc66b","UID":"SSS001","TITLE":"Report five vital values","STATEMENT":"While monitoring is running and the sensor is valid, the monitor shall report the attached patient's heart rate, oxygen saturation, systolic pressure, diastolic pressure, and temperature unchanged.","_LINK":"SSS001"},"33":{"MID":"f6ffa06538f943c7bfe0f67e273d0c9c","UID":"SSS002","TITLE":"Select the limit profile by age","STATEMENT":"Age 18 years or older shall select the adult profile, and age under 18 years shall select the pediatric profile. Adult alarms are heart rate below 50 or above 120 bpm, SpO2 below 90 percent, systolic pressure above 160 mmHg, diastolic pressure above 100 mmHg, and temperature below 35.0 or above 38.0 degrees Celsius. Pediatric alarms are heart rate below 70 or above 160 bpm, SpO2 below 92 percent, systolic pressure above 120 mmHg, diastolic pressure above 80 mmHg, and temperature below 35.5 or above 38.0 degrees Celsius.","_LINK":"SSS002"},"34":{"MID":"7ae49c7d0c4348189df9d95df1c10bd4","UID":"SSS003","TITLE":"Inclusive limits","STATEMENT":"A vital sign equal to its limit shall not raise that vital's alarm.","_LINK":"SSS003"},"35":{"MID":"68cee79d96ca4f9885f9a8f05a5ec7d8","UID":"SSS004","TITLE":"Idle and stopped monitor","STATEMENT":"Before start and after stop, the monitor shall report no alarms and shall not present vitals as valid. start with no patient attached shall be rejected.","_LINK":"SSS004"},"36":{"MID":"14256feaa25b450bb3224f90aa044066","UID":"SSS005","TITLE":"Attach selects the default profile","STATEMENT":"attach shall store the patient and select that patient's default limit profile.","_LINK":"SSS005"},"37":{"MID":"82945a9f3c2548c896fe70c74864aff8","UID":"SSS006","TITLE":"Sensor fault risk control","STATEMENT":"When the sensor is invalid, the monitor shall raise only SENSOR_FAULT and shall not present vitals as valid.","_LINK":"SSS006"},"38":{"MID":"dbfd5771f9d4409898d50f651dd7263f","UID":"SSS007","TITLE":"Reject out-of-range limit command","STATEMENT":"set_limits shall reject a command whose heart-rate low limit is outside 20 through 200, whose heart-rate high limit is outside 30 through 250 or not strictly above the low limit, whose SpO2 low limit is outside 50 through 100, whose systolic high limit is outside 80 through 250, whose diastolic high limit is outside 40 through 150, or whose temperature limits are outside 30.0 through 43.0 or whose temperature high limit is not strictly above the low limit. A rejected command shall not be used for alarm evaluation, and the previously accepted limits shall remain.","_LINK":"SSS007"},"39":{"MID":"3c12f71d56b243acadf654773e7f240c","TITLE":"Test harness","_LINK":"2-Test-harness"},"40":{"MID":"093e9e6a37df42e8aea43b30262064be","UID":"SSS008","TITLE":"Function-scoped fixtures","STATEMENT":"The test harness shall provide function-scoped pytest fixtures named healthy_adult, tachycardic_adult, hypoxic_adult, hypertensive_adult, pediatric_patient, sensor_fault_patient, and patient_monitor, and each fixture shall return a new instance per test.","_LINK":"SSS008"},"41":{"MID":"1d1b487d1c7f46feaabeef4640c8d8bd","UID":"SSS009","TITLE":"HTML test report contents","STATEMENT":"make test shall write a self-contained pytest HTML report to docs/pytest-report.html, including software version 0.1.0, Python and package versions, the date, and the operating-system user as the person who ran the test.","_LINK":"SSS009"},"42":{"MID":"3f32ab3ab0ba4aacb0d7d02bdde5c58a","TITLE":"Remote patient acquisition","_LINK":"3-Remote-patient-acquisition"},"43":{"MID":"a84f9ee8255344c0b7a6b271f5b27157","UID":"SSS010","TITLE":"SOAP GetPatient returns a Human","STATEMENT":"SoapPatientDevice shall return a Human matching the GetPatient body, including sensor_valid false when the body says the sensor is invalid.","_LINK":"SSS010"},"44":{"MID":"f8e776557c51401ca6c9cecbf96e50f9","UID":"SSS011","TITLE":"SOAP fault does not return a patient","STATEMENT":"A SOAP fault or an unknown patient shall not produce a Human.","_LINK":"SSS011"},"45":{"MID":"f211945b3f574bbfb3e823cb8a90b4d6","UID":"SSS012","TITLE":"ReadyAPI patient resource returns a Human","STATEMENT":"ReadyApiPatientDevice shall return a Human matching the JSON patient resource.","_LINK":"SSS012"},"46":{"MID":"875518ba0bd9419993f427a1b5053f2f","UID":"SSS013","TITLE":"Unknown ReadyAPI patient does not return a patient","STATEMENT":"An unknown ReadyAPI patient shall not produce a Human.","_LINK":"SSS013"},"47":{"MID":"2e50c19d6d1d48d998ce2330dd3999a2","TITLE":"Unit tests","_LINK":"1-Unit-tests"},"48":{"MID":"da849d42ec8942818c471eeda9b620b4","UID":"TD001","TITLE":"Age selects population","STATEMENT":"test_age_selects_population shall show that age 18 is not pediatric and age 17 is pediatric.","_LINK":"TD001"},"49":{"MID":"b77e120a43b6490985d11b0a5e916cef","UID":"TD002","TITLE":"Patients inherit from Human","STATEMENT":"test_mock_patients_inherit_from_human shall show that each mock patient is a Human, the pediatric patient is age 8, and the sensor-fault patient has no numeric vitals.","_LINK":"TD002"},"50":{"MID":"9e2220f91413450cb7cd7d25dcf66671","UID":"TD003","TITLE":"Default profiles accepted","STATEMENT":"test_default_profiles_are_accepted shall accept the adult and pediatric defaults and shall map age 18 to adult and age 17 to pediatric.","_LINK":"TD003"},"51":{"MID":"9f8c8634dc0e42f48eb4152663d454ec","UID":"TD004","TITLE":"Reject SpO2 above 100","STATEMENT":"test_rejects_spo2_above_100 shall reject an SpO2 low limit of 101.","_LINK":"TD004"},"52":{"MID":"62695a3bd7ad44c2bf68af4ff7565755","UID":"TD005","TITLE":"Reject heart-rate order","STATEMENT":"test_rejects_heart_rate_high_not_above_low shall reject a heart-rate high limit that is not above the low limit.","_LINK":"TD005"},"53":{"MID":"3e513bc7fe2c44ed89b61a1dcd5a4293","UID":"TD006","TITLE":"Reject temperature order","STATEMENT":"test_rejects_temperature_high_not_above_low shall reject a temperature high limit that is not above the low limit.","_LINK":"TD006"},"54":{"MID":"6049442170624de6984306e75a90a7de","UID":"TD007","TITLE":"Equal to limit","STATEMENT":"test_equal_to_limit_does_not_alarm shall show that adult vitals equal to each limit do not alarm.","_LINK":"TD007"},"55":{"MID":"07779cd8be454b47ac92f637e5338b41","UID":"TD008","TITLE":"One past the limit","STATEMENT":"test_one_past_adult_limits_alarms shall show that one step outside each adult limit raises that alarm.","_LINK":"TD008"},"56":{"MID":"5575d1c9db574fcfba53160d172c2624","UID":"TD009","TITLE":"Pediatric limits differ","STATEMENT":"test_pediatric_limits_differ_from_adult shall show that SpO2 91 and heart rate 140 alarm differently on the adult and pediatric profiles.","_LINK":"TD009"},"57":{"MID":"395d449df0124fabb9b798c610863009","UID":"TD010","TITLE":"Sensor fault unit","STATEMENT":"test_sensor_fault_suppresses_vital_alarms shall show that an invalid sensor raises only SENSOR_FAULT.","_LINK":"TD010"},"58":{"MID":"f20597c52b034af584a41268edbfee37","TITLE":"Integration tests","_LINK":"2-Integration-tests"},"59":{"MID":"7e666fdbc5264bb8bc6364e5198d28f7","UID":"TD011","TITLE":"Healthy adult integration","STATEMENT":"test_healthy_adult_reports_vitals_and_no_alarm shall present the healthy adult vitals unchanged, with the adult profile and no alarm.","_LINK":"TD011"},"60":{"MID":"71eb1ffa3f5f44d5bbb2bc8c45e392aa","UID":"TD012","TITLE":"Tachycardic adult integration","STATEMENT":"test_tachycardic_adult_heart_rate_alarm shall raise only HEART_RATE for the tachycardic adult.","_LINK":"TD012"},"61":{"MID":"5e7c266777104703910ab7f62146627a","UID":"TD013","TITLE":"Hypoxic adult integration","STATEMENT":"test_hypoxic_adult_spo2_alarm shall raise only SPO2 for the hypoxic adult.","_LINK":"TD013"},"62":{"MID":"9abfe1b3f1f340a7ba6d22fbc1b6f21d","UID":"TD014","TITLE":"Hypertensive adult integration","STATEMENT":"test_hypertensive_adult_blood_pressure_alarm shall raise only BLOOD_PRESSURE for the hypertensive adult.","_LINK":"TD014"},"63":{"MID":"35193f9f3dbd4ac189f7e0694aa65256","UID":"TD015","TITLE":"Pediatric integration","STATEMENT":"test_pediatric_patient_uses_pediatric_profile shall select the pediatric profile and shall not alarm at heart rate 140.","_LINK":"TD015"},"64":{"MID":"d010e48dd02a455084d747dacf7b1c28","UID":"TD016","TITLE":"Sensor fault integration","STATEMENT":"test_sensor_fault_patient_hides_vitals shall hide numeric vitals and raise only SENSOR_FAULT.","_LINK":"TD016"},"65":{"MID":"88286e2de6e04ddb8045fd6c78b3a0eb","UID":"TD017","TITLE":"Rejected limits integration","STATEMENT":"test_rejected_limits_leave_the_adult_profile shall keep the adult profile after a rejected command and shall not alarm the healthy adult.","_LINK":"TD017"},"66":{"MID":"866311e213a34290859c3a7e6f1f416c","UID":"TD018","TITLE":"Idle and stopped integration","STATEMENT":"test_idle_and_stopped_monitor_has_no_alarms shall report no alarms before start and after stop, and shall alarm only while running.","_LINK":"TD018"},"67":{"MID":"bdc51bfcd07742e8b09cb9d44305fc5b","TITLE":"Software system tests","_LINK":"3-Software-system-tests"},"68":{"MID":"e3193638a8a84564afcbe893446a8f90","UID":"TD019","TITLE":"System vitals","STATEMENT":"test_system_reports_attached_vitals shall present the five healthy-adult vital values while monitoring is running.","_LINK":"TD019"},"69":{"MID":"c78bea68e0d04fa890eaca2a699fae9b","UID":"TD020","TITLE":"System profile by age","STATEMENT":"test_system_profile_follows_age shall apply the adult profile to the healthy adult and the pediatric profile to the pediatric patient.","_LINK":"TD020"},"70":{"MID":"1576b1829fea41bd8cb7a0d8db7bb72a","UID":"TD021","TITLE":"System boundary","STATEMENT":"test_system_boundary_value_does_not_alarm shall not alarm at heart rate 120 and shall alarm at heart rate 121 on the adult profile.","_LINK":"TD021"},"71":{"MID":"a91ca834405f4a5189c7f4931b0901a7","UID":"TD022","TITLE":"System start and stop","STATEMENT":"test_system_start_and_stop shall reject start with no patient and shall clear alarms after stop.","_LINK":"TD022"},"72":{"MID":"ef46c9e2c6ac43e59629a6fc52155af9","UID":"TD023","TITLE":"System attach","STATEMENT":"test_system_attach_stores_patient_and_profile shall store the pediatric patient and select the pediatric profile.","_LINK":"TD023"},"73":{"MID":"af131714ced44126a40ec4294dcbecec","UID":"TD024","TITLE":"System sensor fault","STATEMENT":"test_system_sensor_fault shall raise only SENSOR_FAULT and shall not present vitals as valid.","_LINK":"TD024"},"74":{"MID":"d68efeb3e5fb4271b99d169ebb7b390f","UID":"TD025","TITLE":"System rejected command","STATEMENT":"test_system_rejects_out_of_range_command shall keep the previous limits and shall not alarm the healthy adult after a rejected command.","_LINK":"TD025"},"75":{"MID":"442ef81b2beb4c8e9015ac5b83bb1665","UID":"TD026","TITLE":"Fixture scope","STATEMENT":"test_fixtures_are_function_scoped shall show that each required fixture is function scoped.","_LINK":"TD026"},"76":{"MID":"58a9833b4291405b8336fdd2d20cdae6","UID":"TD027","TITLE":"HTML report configuration","STATEMENT":"test_html_report_path_and_metadata shall show that the report path is docs/pytest-report.html, that the HTML is self-contained, and that version 0.1.0, the device configuration, the tools, and the operator are recorded.","_LINK":"TD027"},"77":{"MID":"37ac7cdaa1a645e1a2ce2bd432884b3f","TITLE":"Remote acquisition tests","_LINK":"4-Remote-acquisition-tests"},"78":{"MID":"704aaaa022d74cf0aa152f74ecdc6bca","UID":"TD028","TITLE":"SOAP returns a patient","STATEMENT":"test_dispatch_returns_registered_patient and test_soap_device_returns_healthy_adult shall return the registered patient fields.","_LINK":"TD028"},"79":{"MID":"62222bdd57ff46c48382c9f6beb0ea96","UID":"TD029","TITLE":"SOAP sensor fault","STATEMENT":"test_dispatch_omits_invalid_sensor_vitals and test_soap_device_returns_sensor_fault shall preserve sensor_valid false.","_LINK":"TD029"},"80":{"MID":"d089d30be3644859998f524fef73829c","UID":"TD030","TITLE":"SOAP unknown patient","STATEMENT":"test_dispatch_unknown_patient_is_a_fault and test_soap_device_unknown_patient_raises shall not produce a Human for an unknown id.","_LINK":"TD030"},"81":{"MID":"3a71021d943d4d649b3fea1746569b94","UID":"TD031","TITLE":"SOAP malformed request","STATEMENT":"test_dispatch_malformed_xml_is_a_fault shall return a SOAP fault for a body that is not XML.","_LINK":"TD031"},"82":{"MID":"2b8cbeede2f8400a9b4a4693b75617e0","UID":"TD032","TITLE":"ReadyAPI returns a patient","STATEMENT":"test_readyapi_device_returns_healthy_adult shall return the healthy adult fields.","_LINK":"TD032"},"83":{"MID":"ee0c9f618c2c4c10a64afd0be74bf263","UID":"TD033","TITLE":"ReadyAPI pediatric patient","STATEMENT":"test_readyapi_device_returns_pediatric_patient shall return the pediatric patient fields.","_LINK":"TD033"},"84":{"MID":"206ade998be84b7b9dfaaacec10d2e7b","UID":"TD034","TITLE":"ReadyAPI sensor fault","STATEMENT":"test_readyapi_device_returns_sensor_fault shall preserve an invalid sensor.","_LINK":"TD034"},"85":{"MID":"ef2e869ebe0d4549ab2c28218ae29639","UID":"TD035","TITLE":"SOAP sensor fault on the monitor","STATEMENT":"test_soap_sensor_fault_still_alarms_on_monitor shall raise only SENSOR_FAULT after the patient is fetched over SOAP.","_LINK":"TD035"},"86":{"MID":"5a0426871b124ff993c9b2348e67b8ff","UID":"TD036","TITLE":"ReadyAPI unknown patient","STATEMENT":"test_readyapi_device_unknown_patient_raises shall not produce a Human for an unknown id.","_LINK":"TD036"},"87":{"MID":"b49df435f88149d286134607ea1097db","UID":"TD037","TITLE":"ReadyAPI sensor fault on the monitor","STATEMENT":"test_readyapi_sensor_fault_still_alarms_on_monitor shall raise only SENSOR_FAULT after the patient is fetched from ReadyAPI.","_LINK":"TD037"},"88":{"MID":"609138ff1e34465483394833c104a342","TITLE":"Verification plan","_LINK":"1-Verification-plan"},"89":{"MID":"a7e1a07f2fce4f609ca12a8163420cb8","UID":"TP001","TITLE":"Unit tests before integration","STATEMENT":"Unit tests in tests/unit shall be executed before integration tests. They shall cover limit acceptance, inclusive boundaries, profile selection, and sensor fault.","_LINK":"TP001"},"90":{"MID":"414e79f754b24ae19c18e35100b29b74","UID":"TP002","TITLE":"Integration with each patient","STATEMENT":"Integration tests in tests/integration shall combine PatientMonitor with each patient fixture.","_LINK":"TP002"},"91":{"MID":"c0fd1cecbc094d8da7ce7ce0b32a9809","UID":"TP003","TITLE":"System coverage","STATEMENT":"System tests in tests/system shall cover every SSS requirement, including the risk controls SSS006 and SSS007.","_LINK":"TP003"},"92":{"MID":"a130a2ff52164eea9496fe855991614f","UID":"TP004","TITLE":"HTML record","STATEMENT":"The test record shall be docs/pytest-report.html produced by make test, and pytest shall collect tests/unit, then tests/integration, then tests/system.","_LINK":"TP004"},"93":{"MID":"aabbae6521a24788b74f700cc5b40ead","UID":"TP005","TITLE":"Remote acquisition tests","STATEMENT":"Tests shall cover SOAP GetPatient and the ReadyAPI patient resource, including a successful patient, an unknown patient, and a sensor-fault patient attached to PatientMonitor.","_LINK":"TP005"}};
